#include <stdlib.h>
int main(void){volatile int *p=(volatile int*)malloc(sizeof(int)); if(!p)return 2; *p=7;
#if BAD
free((void*)p);
#endif
int v=*p;
#if !BAD
free((void*)p);
#endif
return v==7?0:1;}

#if BAD
__attribute__((noinline)) int *f(void){int x=7; return &x;}
#else
int x=7; __attribute__((noinline)) int *f(void){return &x;}
#endif
int main(void){volatile int *p=f(); return *p==7?0:1;}

struct B {virtual ~B() {}}; struct D:B {int x=7;}; int main(){
#if BAD
B *b=new B;
#else
B *b=new D;
#endif
D *d=static_cast<D*>(b); int v=d->x; delete b; return v==7?0:1;}
